            amzOutput = float4(v, 0.0, 1.0);
            return;
        }
        if (amzPass == 1) {
            float2 v = amzp_smoothing > 0.05 ? blur9(1, float2(0.0, 1.0), false) : amzTexture(1, uv).rg;
            amzOutput = float4(v, 0.0, 1.0);
            return;
        }
        if (amzPass == 2) {
            float2 tl = amzTexture(2, uv + float2(-1.0, 1.0) * p1).rg;
            float2 tc = amzTexture(2, uv + float2(0.0, 1.0) * p1).rg;
            float2 tr = amzTexture(2, uv + float2(1.0, 1.0) * p1).rg;
            float2 ml = amzTexture(2, uv + float2(-1.0, 0.0) * p1).rg;
            float2 mr = amzTexture(2, uv + float2(1.0, 0.0) * p1).rg;
            float2 bl = amzTexture(2, uv + float2(-1.0, -1.0) * p1).rg;
            float2 bc = amzTexture(2, uv + float2(0.0, -1.0) * p1).rg;
            float2 br = amzTexture(2, uv + float2(1.0, -1.0) * p1).rg;
            float2 gx = (3.0 * (tr + br - tl - bl) + 10.0 * (mr - ml)) / 16.0;
