            float2 g = float2(gx.x, gy.x);
            if ((amzp_alphaEdges>0.5)) {
                float2 ga = float2(gx.y, gy.y);
                if (dot(ga, ga) > dot(g, g)) g = ga;
            }
            float m = length(g) * amzp_strength;
            float2 d = m > 1e-5 ? normalize(g) : float2(1.0, 0.0);
            amzOutput = float4(clamp(m, 0.0, 1.0), d * 0.5 + 0.5, 1.0);
            return;
        }
        if (amzPass == 3) {
            float4 g = amzTexture(3, uv);
            float m = g.r;
            float2 d = g.gb * 2.0 - 1.0;
            if ((amzp_thin>0.5)) {
                float m1 = magAt(uv + d * p1);
                float m2 = magAt(uv - d * p1);
                float keep = smoothstep(-0.004, 0.004, m - max(m1, m2));
                m *= keep;
            }
            float th = amzp_threshold, sf = max(amzp_softness, 0.001);
            float e = smoothstep(th - sf * 0.5, th + sf * 0.5, m);
            if (!(amzp_thin>0.5)) e *= clamp(m * 2.0, 0.0, 1.0) * 0.5 + 0.5;
            amzOutput = float4(e, 0.0, 0.0, 1.0);
            return;
        }
        float w = amzp_lineW * pxs();
        float e = amzTexture(4, uv).r;
        if (w > 1.05) {
            float r = (w - 1.0) * 0.5;
            for (int i = 0; i < 12; i++) {
                float a = float(i) * 6.28318531 / 12.0;
                float2 o = float2(cos(a), sin(a));
                float v1 = amzTexture(4, uv + o * r * p1).r;
                float v2 = amzTexture(4, uv + o * r * 0.5 * p1).r;
                e = max(e, max(v1, v2));
            }
        }
        float4 orig = amzTexture(0, uv);
        float3 oc = orig.a > 0.0001 ? orig.rgb / orig.a : float3(0.0);
        float3 lc = amzp_lineCol.rgb;
        if ((amzp_fromSrc>0.5)) {
            float3 s = oc;
            float l = luma(s);
            s = clamp(mix(float3(l), s, amzp_srcBoost) * mix(1.0, 1.0 / max(max(s.r, max(s.g, s.b)), 0.05), clamp(amzp_srcBoost - 1.0, 0.0, 1.0)), 0.0, 1.0);
            lc = s;
        }
        float4 R;
        if (int(amzp_bgMode) == 0) R = float4(mix(float3(1.0), lc, e) * orig.a, orig.a);
        else if (int(amzp_bgMode) == 1) R = float4(mix(float3(0.0), lc, e) * orig.a, orig.a);
        else if (int(amzp_bgMode) == 2) R = float4(lc * e, e);
        else R = float4(mix(oc, lc, e) * orig.a, orig.a);
        amzOutput = mix(orig, R, clamp(amzp_mixAmt, 0.0, 1.0));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

